(11787, 11, 185, '맛집', '음식특화거리', '장기먹거리촌', '대단지 아파트가 밀집해 있는 용산네거리와 감천네거리 사이에 위치 해 있고 대규모 공영주차장을 중심으로 골목 사이사이 크고 작은 음식점이 밀집되어 있는 음식문화거리로, 술집이 많아 저녁이면 더욱 활성화되는 곳이고 인근에 무지개공원과 장기동 편백나무 숲에 맨발 산책로가 조성되어 있다.', '대구광역시 달서구 대명천로 290 일대(장기동)', NULL, 35.84187528, 128.5286924, '053-667-2782', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '대구광역시 달서구청', NULL, NULL, 5, '8a28fcaedb4a07ff31967580cdaecccad78f35eee36697aa32de769a5964eea2', '2026-03-07', '{"거리명": "장기먹거리촌", "거리소개": "대단지 아파트가 밀집해 있는 용산네거리와 감천네거리 사이에 위치 해 있고 대규모 공영주차장을 중심으로 골목 사이사이 크고 작은 음식점이 밀집되어 있는 음식문화거리로, 술집이 많아 저녁이면 더욱 활성화되는 곳이고 인근에 무지개공원과 장기동 편백나무 숲에 맨발 산책로가 조성되어 있다.", "소재지도로명": "대구광역시 달서구 대명천로 290 일대(장기동)", "위도": "35.84187528", "경도": "128.5286924", "총길이": "895", "점포수": "91", "지정연도": "2024", "관리기관전화번호": "053-667-2782", "관리기관명": "대구광역시 달서구청", "데이터기준일자": "2026-03-07", "제공기관코드": "3470000", "제공기관명": "대구광역시 달서구"}', '2026-10-12 07:34:02'),
(11788, 11, 185, '맛집', '음식특화거리', '모다음식문화거리', '모다아울렛 주변 의료상가를 중심으로 성서공단 3차 첨단산업단지가 있는 음식문화거리로 교통, 주차, 쇼핑 숙박시설 등 입지조건 및 제반여건이 양호하고 시설환경 수준이 높고 대형 외식업소가 많은 곳으로 다양한 음식점이 분포되어 있으며 인근 관광지로 대명유수지, 계명대캠퍼스 등이 있다.', '대구광역시 달서구 성서공단로15길 일대(신당동)', NULL, 35.83916285, 128.4903964, '053-667-2782', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '대구광역시 달서구청', NULL, NULL, 5, '1e10897f22de84f9536a5faaa98ae31c83b4b274d5d22f0227535ef386aaa046', '2026-03-07', '{"거리명": "모다음식문화거리", "거리소개": "모다아울렛 주변 의료상가를 중심으로 성서공단 3차 첨단산업단지가 있는 음식문화거리로 교통, 주차, 쇼핑 숙박시설 등 입지조건 및 제반여건이 양호하고 시설환경 수준이 높고 대형 외식업소가 많은 곳으로 다양한 음식점이 분포되어 있으며 인근 관광지로 대명유수지, 계명대캠퍼스 등이 있다.", "소재지도로명": "대구광역시 달서구 성서공단로15길 일대(신당동)", "위도": "35.83916285", "경도": "128.4903964", "총길이": "860", "점포수": "108", "지정연도": "2024", "관리기관전화번호": "053-667-2782", "관리기관명": "대구광역시 달서구청", "데이터기준일자": "2026-03-07", "제공기관코드": "3470000", "제공기관명": "대구광역시 달서구"}', '2026-10-12 07:34:02'),
(11789, 11, 185, '맛집', '음식특화거리', '이곡으뜸길 음식문화거리', '국민연금공단, 차량등록사업소, 성서경찰서 등 인근 공공기관과 대단지 아파트가 어우러져 근로자들의 회식 및 가족 모임 장소로 사랑받고 있는 음식문화거리로 지하철 2호선 성서산업단지역과의 접근성이 좋으며 인근 에 배실웨딩공원, 성서국민체육센터 등이 있다.', '대구광역시 달서구 달구벌대로251길 일대(이곡동)', NULL, 35.797227, 128.548106, '053-667-2782', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '대구광역시 달서구청', NULL, NULL, 5, '7ec043baa1dc23eceb3fe13d7cdd6044253013901321c0ec2b071fa017ef80d7', '2026-03-07', '{"거리명": "이곡으뜸길 음식문화거리", "거리소개": "국민연금공단, 차량등록사업소, 성서경찰서 등 인근 공공기관과 대단지 아파트가 어우러져 근로자들의 회식 및 가족 모임 장소로 사랑받고 있는 음식문화거리로 지하철 2호선 성서산업단지역과의 접근성이 좋으며 인근 에 배실웨딩공원, 성서국민체육센터 등이 있다.", "소재지도로명": "대구광역시 달서구 달구벌대로251길 일대(이곡동)", "위도": "35.797227", "경도": "128.548106", "총길이": "590", "점포수": "126", "지정연도": "2023", "관리기관전화번호": "053-667-2782", "관리기관명": "대구광역시 달서구청", "데이터기준일자": "2026-03-07", "제공기관코드": "3470000", "제공기관명": "대구광역시 달서구"}', '2026-10-12 07:34:02'),
