(11864, 11, 182, '맛집', '음식특화거리', '봉덕맛길', '봉덕 구길의 맛 집 등을 재정비하여 찾아가고 싶고 맛이 어우러지는 옛 향기골목으로 새로이 조성하고자 2009년부터 정비공사를 실시하여 현재에 이러렀고 미식가들에게 휴식공간을 제공하고 안전한 먹거리, 특색있는 맛집골목으로 독창성을 발휘하여 남구의 새로운 랜드마크로 거듭났다.', '대구광역시 남구 중앙대로 22길 273', '대구광역시 남구 봉덕동 879-14', 35.84169326, 128.6057273, '053-664-2762', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '대구광역시 남구청', NULL, NULL, 5, '3147d28517a7299b9f04cea443d0332c8219483859bf994953443188a7c40961', '2025-10-27', '{"거리명": "봉덕맛길", "거리소개": "봉덕 구길의 맛 집 등을 재정비하여 찾아가고 싶고 맛이 어우러지는 옛 향기골목으로 새로이 조성하고자 2009년부터 정비공사를 실시하여 현재에 이러렀고 미식가들에게 휴식공간을 제공하고 안전한 먹거리, 특색있는 맛집골목으로 독창성을 발휘하여 남구의 새로운 랜드마크로 거듭났다.", "소재지도로명": "대구광역시 남구 중앙대로 22길 273", "소재지지번주소": "대구광역시 남구 봉덕동 879-14", "위도": "35.84169326", "경도": "128.6057273", "총길이": "700", "점포수": "35", "지정연도": "2009", "관리기관전화번호": "053-664-2762", "관리기관명": "대구광역시 남구청", "데이터기준일자": "2025-10-27", "제공기관코드": "3440000", "제공기관명": "대구광역시 남구"}', '2026-10-12 07:34:02'),
(11865, 11, 182, '맛집', '음식특화거리', '앞산맛둘레길', '1950년대부터 앞산공원이 개발되고 등산객들을 상대로 하는 식당들이 생겨났음. 앞산순환도로를 따라 지금처럼 많은 음식점들이 들어서게 되었으며 규모와 분위기는 들안길과 비슷하지만 앞산이라는 자연경관과 함께 여유롭게 즐길수 있는 곳임', '대구광역시 남구 앞산순환로 429', '대구광역시 남구 대명동 553-5', 35.8309432, 128.5727651, '053-664-2762', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '대구광역시 남구청', NULL, NULL, 5, '4444e66793945df53d7cf834f497358b754e2724f03d03b365b6a8efab98fe1b', '2025-10-27', '{"거리명": "앞산맛둘레길", "거리소개": "1950년대부터 앞산공원이 개발되고 등산객들을 상대로 하는 식당들이 생겨났음. 앞산순환도로를 따라 지금처럼 많은 음식점들이 들어서게 되었으며 규모와 분위기는 들안길과 비슷하지만 앞산이라는 자연경관과 함께 여유롭게 즐길수 있는 곳임", "소재지도로명": "대구광역시 남구 앞산순환로 429", "소재지지번주소": "대구광역시 남구 대명동 553-5", "위도": "35.8309432", "경도": "128.5727651", "총길이": "1500", "점포수": "57", "지정연도": "2010", "관리기관전화번호": "053-664-2762", "관리기관명": "대구광역시 남구청", "데이터기준일자": "2025-10-27", "제공기관코드": "3440000", "제공기관명": "대구광역시 남구"}', '2026-10-12 07:34:02'),
(11866, 11, 182, '맛집', '음식특화거리', '남구바다맛길', '대구문화예술회관 옆 성당못에서 서부정류장쪽으로 달리다 보면 왼편에 대형 회타운이 보인다. 여기가 속칭 남구 대명10동 ’복개천 번개어시장 회골목’. 93년쯤 복개천이 완공되자 수산물 도매상인들까지 대거 이곳으로 몰려들어 전성기엔 40개 업소가 북적 거렸다고 한다.', '대구광역시 남구 대명복개로 9-2', '대구광역시 남구 대명동 1225-38', 35.83978823, 128.5600566, '053-664-2762', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '대구광역시 남구청', NULL, NULL, 5, '93b4cc68f01f003dc375c7a0d0d253befb20e4a51a94c922ee254b8e97aa448b', '2025-10-27', '{"거리명": "남구바다맛길", "거리소개": "대구문화예술회관 옆 성당못에서 서부정류장쪽으로 달리다 보면 왼편에 대형 회타운이 보인다. 여기가 속칭 남구 대명10동 ’복개천 번개어시장 회골목’. 93년쯤 복개천이 완공되자 수산물 도매상인들까지 대거 이곳으로 몰려들어 전성기엔 40개 업소가 북적 거렸다고 한다.", "소재지도로명": "대구광역시 남구 대명복개로 9-2", "소재지지번주소": "대구광역시 남구 대명동 1225-38", "위도": "35.83978823", "경도": "128.5600566", "총길이": "200", "점포수": "20", "지정연도": "2011", "관리기관전화번호": "053-664-2762", "관리기관명": "대구광역시 남구청", "데이터기준일자": "2025-10-27", "제공기관코드": "3440000", "제공기관명": "대구광역시 남구"}', '2026-10-12 07:34:02'),
(11867, 11, 182, '맛집', '음식특화거리', '안지랑곱창골목', '안지랑 오거리에서 앞산 안지랑골로 통하는 길 중간에 형성된 안지랑 시장은 화려한 명성을 뒤로 하고 최근 양념 곱창집이 들어차 새로운 활력이 되고 있다. 1979년 경 안지랑 시장 쪽에 충북식당을 시작으로 1998년 IMF이후 생계유지 업소가 늘어나기 시작해 오늘에 이르렀다. 서민들이 부담없이 즐길수 있는 휴식처이자 최근엔 젊은층이 주도하는 젊음의 거리로 발전하였으며, 2012년도 전국5대 음식테마거리, 2015 한국관광100선에 선정되는 등 남구대표 맛거리로 전국은 물론 해외관광객들이 자주 찾는 명소이다', '대구광역시 남구 안지랑로 16길 67', '대구광역시 남구 대명동 829-2', 35.83685644, 128.5751543, '053-664-2762', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '대구광역시 남구청', NULL, NULL, 5, 'a30a3cc05834f9d8b2fd161fab833d8b1a44cdccd7b14b918148c74badc003d3', '2025-10-27', '{"거리명": "안지랑곱창골목", "거리소개": "안지랑 오거리에서 앞산 안지랑골로 통하는 길 중간에 형성된 안지랑 시장은 화려한 명성을 뒤로 하고 최근 양념 곱창집이 들어차 새로운 활력이 되고 있다. 1979년 경 안지랑 시장 쪽에 충북식당을 시작으로 1998년 IMF이후 생계유지 업소가 늘어나기 시작해 오늘에 이르렀다. 서민들이 부담없이 즐길수 있는 휴식처이자 최근엔 젊은층이 주도하는 젊음의 거리로 발전하였으며, 2012년도 전국5대 음식테마거리, 2015 한국관광100선에 선정되는 등 남구대표 맛거리로 전국은 물론 해외관광객들이 자주 찾는 명소이다", "소재지도로명": "대구광역시 남구 안지랑로 16길 67", "소재지지번주소": "대구광역시 남구 대명동 829-2", "위도": "35.83685644", "경도": "128.5751543", "총길이": "500", "점포수": "70", "지정연도": "2011", "관리기관전화번호": "053-664-2762", "관리기관명": "대구광역시 남구청", "데이터기준일자": "2025-10-27", "제공기관코드": "3440000", "제공기관명": "대구광역시 남구"}', '2026-10-12 07:34:02'),
(11868, 11, 182, '맛집', '음식특화거리', '앞산카페거리', '일반주택들을 커피숍으로 리모델링 되어 형성된 대구광역시 남구 대명9동 일대를 앞산카페거리라 한다이곳에는 갤러리카페, 양옥집을 개조한 이탈리아 레스토랑 등 약50여개의 다양하고 매력적인 공간들이 즐비해 도심속의 이국적인 분위기를 연출한다또한 흐트러지게핀 벚꽃과, 이팝나무의 새하얀 꽃을 보며 봄의 정취를, 여름엔 앞산에서 불어오는 시원한 바람이, 가을에는 가로수들 사이로 떨어지는 은행잎을 밟으며 가을 낭만도 한껏 느낄수 있고, 겨울앤 앙상한 가지에 수천개가 넘는 꼬마전구의 화려한 빛의 향연을 볼 수 있다', '대구광역시 남구 대명로 232-2', '대구광역시 남구 대명동 1291', 35.84115783, 128.5822578, '053-664-2762', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '대구광역시 남구청', NULL, NULL, 5, '3d878836d8730e35ed7b3c027d9bc3d49330a374abe07c47adc8e8bd1f600596', '2025-10-27', '{"거리명": "앞산카페거리", "거리소개": "일반주택들을 커피숍으로 리모델링 되어 형성된 대구광역시 남구 대명9동 일대를 앞산카페거리라 한다이곳에는 갤러리카페, 양옥집을 개조한 이탈리아 레스토랑 등 약50여개의 다양하고 매력적인 공간들이 즐비해 도심속의 이국적인 분위기를 연출한다또한 흐트러지게핀 벚꽃과, 이팝나무의 새하얀 꽃을 보며 봄의 정취를, 여름엔 앞산에서 불어오는 시원한 바람이, 가을에는 가로수들 사이로 떨어지는 은행잎을 밟으며 가을 낭만도 한껏 느낄수 있고, 겨울앤 앙상한 가지에 수천개가 넘는 꼬마전구의 화려한 빛의 향연을 볼 수 있다", "소재지도로명": "대구광역시 남구 대명로 232-2", "소재지지번주소": "대구광역시 남구 대명동 1291", "위도": "35.84115783", "경도": "128.5822578", "총길이": "1000", "점포수": "66", "지정연도": "2010", "관리기관전화번호": "053-664-2762", "관리기관명": "대구광역시 남구청", "데이터기준일자": "2025-10-27", "제공기관코드": "3440000", "제공기관명": "대구광역시 남구"}', '2026-10-12 07:34:02'),
